import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getCarById, updateCarById } from "../../services/ApiCar";

export default function UpdateVoiture() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [car, setCar] = useState({
    model: "",
    matricule: "",
    prix: ""
  });

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const res = await getCarById(id);
        setCar(res.data);
      } catch (err) {
        console.log(err);
      }
    };
    fetchCar();
  }, [id]);

  const handleChange = (e) => {
    setCar({ ...car, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await updateCarById(id, car);
      navigate("/admin/voitures"); // redirection après modification
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="p-4 max-w-md mx-auto">
      <h2 className="text-xl mb-4">Modifier Voiture</h2>
      <input name="model" value={car.model} onChange={handleChange} placeholder="Model" className="w-full p-2 mb-2 border" />
      <input name="matricule" value={car.matricule} onChange={handleChange} placeholder="Matricule" className="w-full p-2 mb-2 border" />
      <input name="prix" value={car.prix} onChange={handleChange} placeholder="Prix" className="w-full p-2 mb-2 border" />
      <button type="submit" className="bg-blue-500 text-white px-4 py-2 rounded">✅ Modifier</button>
    </form>
  );
}
